rng=np.random.default_rng(712649)
shift=np.array([-.1]+[.5]*9+[5]*10);scale=np.array([4.1]+[.5]*9+[5]*10)
desc=[["intercept"]]+[["linear",j] for j in range(20)]
for j in [0]+list(range(10,20)):
    for knot in [-.5,0,.5]:desc.append(["hinge",j,knot])
p0=len(desc)
for j in range(20):
    for k in range(j+1,20):
        for a in range(4 if j==0 or j>=10 else 1):
            for b in range(4 if k>=10 else 1):
                desc.append(["interaction",j,k,a,b])
p=len(desc)
def sample(n):
    X=rng.uniform(0,10,(n,20));X[:,0]=rng.uniform(-4.2,4,n);X[:,1:10]=rng.integers(0,2,(n,9))
    return X
def design(X):
    Z=(X-shift)/scale;n=len(X)
    bs=[[Z[:,j]] for j in range(20)]
    for j in [0]+list(range(10,20)):
        bs[j]+=[np.maximum(Z[:,j]-t,0) for t in [-.5,0,.5]]
    D=np.empty((n,p));D[:,0]=1
    for h,a in enumerate(desc[1:]):
        if a[0]=="linear": D[:,h+1]=Z[:,a[1]]
        elif a[0]=="hinge":D[:,h+1]=np.maximum(Z[:,a[1]]-a[2],0)
        else:D[:,h+1]=bs[a[1]][a[3]]*bs[a[2]][a[4]]
    return D
