R=G[p0:,p0:]-G[p0:,:p0]@Bm;r=rhs[p0:]-G[p0:,:p0]@bm
sd=np.sqrt(np.diag(R));R=R/sd[:,None]/sd[None,:];r=r/sd
c=np.zeros(len(r))
for lam in [.007,.005,.003,.002,.001,0]:
    if lam==0:c=np.linalg.solve(R+np.eye(len(r))*1e-7,r)
    else:
        resid=r-R@c
        for epoch in range(1400):
            big=0
