                val=c[k]+resid[k]/R[k,k];new=np.sign(val)*max(abs(val)-lam/R[k,k],0);delta=new-c[k]
                if delta!=0:resid-=R[:,k]*delta;c[k]=new;big=max(big,abs(delta))
